<template>
  <div class="page-container fade-enter-active">
    <header class="page-header"><div><h2>行程价格追踪</h2><p>本地真实查询快照，不代表实时价格</p></div><a-popconfirm title="将清除本地查询快照、价格记录和全部关注行程，无法恢复。" ok-text="全部清除" cancel-text="取消" @confirm="historyStore.clearHistory"><a-button danger type="text">清空历史</a-button></a-popconfirm></header>
    <a-spin :spinning="historyStore.loading"><template v-if="journeys.length">
      <a-segmented v-model:value="section" :options="sectionOptions" block class="section-switch" />
      <section class="journey-list"><button v-for="journey in sectionJourneys" :key="journey.journeyKey" class="journey-card" :class="{ selected: journey.journeyKey === selectedJourneyKey }" @click="selectJourney(journey.journeyKey)"><div><strong>{{ journey.label }}</strong><span>{{ journey.latest.query.departureDate }} · {{ freshness(journey.latest.updatedAt).label }}</span></div><div class="journey-price"><b>¥{{ journey.latestLowest ?? '—' }}</b><em :class="deltaClass(journey.latestDelta)">{{ deltaText(journey.latestDelta) }}</em></div></button></section>
      <template v-if="selectedJourney">
        <section class="overview-card"><div class="overview-heading"><div class="journey-heading-copy"><span class="eyebrow">当前行程</span><h3>{{ selectedJourney.label }}</h3><span class="muted">最近采集：{{ formatTime(selectedJourney.latest.updatedAt) }} · {{ selectedJourney.successfulPlatforms }}/4 平台完成</span></div><a-tag class="freshness-tag" :color="freshnessColor">{{ freshness(selectedJourney.latest.updatedAt).label }}</a-tag></div><a-alert v-if="legacyRoundTrip" type="warning" show-icon message="旧版往返记录" description="该记录可能混合了去程和返程单程价格，已保留供查看，但不参与趋势、历史低点或自动监控。" /><a-alert v-else-if="selectedJourney.latest.query.tripType === 'roundtrip' && !canMonitor" type="info" show-icon message="尚未采到平台原生往返套餐" description="去程和返程仅作为分段参考价，不能建立往返价格提醒。" /><div class="metric-grid"><div><span>最近最低</span><strong>¥{{ selectedJourney.latestLowest ?? '—' }}</strong></div><div><span>历史低点</span><strong>¥{{ selectedJourney.historicalLow ?? '—' }}</strong></div><div><span>较上次</span><strong :class="deltaClass(selectedJourney.latestDelta)">{{ deltaText(selectedJourney.latestDelta) }}</strong></div></div><p class="decision-note">{{ decisionText }}</p><div class="action-row"><a-button type="primary" @click="rerunJourney">立即重新比价</a-button><a-input-number v-model:value="targetPrice" :min="1" :controls="false" prefix="¥" placeholder="可选目标价" :disabled="!canMonitor" /><a-switch v-model:checked="monitorEnabled" checked-children="自动监控" un-checked-children="仅关注" :disabled="!canMonitor" /><a-button @click="saveWatch">{{ currentWatch ? '保存关注' : '添加关注' }}</a-button><a-button v-if="currentWatch" danger type="text" @click="removeWatch">取消关注</a-button></div><p v-if="currentWatch" class="monitor-status">{{ monitorSummary }}</p></section>
        <a-tabs class="history-tabs"><a-tab-pane key="matrix" tab="同航班比价"><section class="panel-card"><h3>四平台价格矩阵</h3><div v-if="matrixRows.length" class="matrix-list"><article v-for="row in matrixRows" :key="row.key" class="matrix-card"><div class="matrix-title"><strong>{{ row.flightNumber }}</strong><span>{{ row.airline }} · {{ row.departureTime }} → {{ row.arrivalTime }}</span><a-tag :color="row.direct ? 'green' : 'orange'">{{ row.direct ? '直飞' : '经停/中转' }}</a-tag></div><div class="platform-grid"><div v-for="platform in platforms" :key="platform" :class="{ best: row.prices[platform] && priceOf(row.prices[platform]!) === row.lowestPrice }"><span>{{ platformLabel(platform) }}</span><template v-if="row.prices[platform]"><strong>¥{{ priceOf(row.prices[platform]!) }}</strong><a-button type="link" size="small" @click="openBooking(row.prices[platform]!)">去订票</a-button></template><em v-else>未查到</em></div></div></article></div><p v-else class="empty-inline">当前快照没有可比较的同航班数据。</p></section></a-tab-pane>
          <a-tab-pane key="trend" tab="趋势与快照"><section class="panel-card"><h3>每次查询最低可比价</h3><p class="muted">{{ selectedJourney.sampleCount < 3 ? '样本不足，仅展示真实记录。' : '趋势仅供参考，库存和票价会实时变化。' }}</p><JourneyTrendChart :points="trendPoints" /></section><section class="panel-card compare-card"><h3>两次快照对比</h3><div class="snapshot-picker"><a-select v-model:value="previousSnapshotId" :options="snapshotOptions" placeholder="较早快照" /><a-select v-model:value="currentSnapshotId" :options="snapshotOptions" placeholder="较新快照" /></div><div v-if="comparison" class="change-list"><div v-for="change in comparison.platformChanges" :key="change.platform" class="change-row"><span>{{ platformLabel(change.platform) }}</span><span>{{ priceText(change.previous) }} → {{ priceText(change.current) }}</span><strong :class="deltaClass(change.delta)">{{ deltaText(change.delta) }}</strong></div></div><p v-else class="empty-inline">至少选择两次不同快照。</p></section><section class="panel-card"><h3>查询快照</h3><button v-for="snapshot in selectedJourney.snapshots" :key="snapshot.id" class="snapshot-item" @click="currentSnapshotId = snapshot.id"><span>{{ formatTime(snapshot.updatedAt) }}</span><b>{{ priceText(snapshotLowest(snapshot)) }}</b></button></section></a-tab-pane></a-tabs>
      </template>
    </template><div v-else class="empty-state"><h3>还没有可用的价格快照</h3><p>完成一次比价后，这里会按行程保存真实价格变化。</p></div></a-spin>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue"; import { useRouter } from "vue-router";
import { Alert as AAlert, Button as AButton, InputNumber as AInputNumber, Popconfirm as APopconfirm, Segmented as ASegmented, Spin as ASpin, TabPane as ATabPane, Tabs as ATabs, Tag as ATag, Select as ASelect, Switch as ASwitch } from "ant-design-vue";
import JourneyTrendChart from "../components/JourneyTrendChart.vue"; import { useHistoryStore } from "../stores/history"; import { useQueryStore } from "../stores/query";
import { buildFlightPriceMatrix, buildJourneySummaries, buildTrendPoints, compareSnapshots, snapshotLowest } from "@/core/analytics/history-analysis"; import { getPriceFreshness } from "@/core/analytics/price-freshness"; import { FlightResult, SupportedPlatform } from "@/shared/types/flight"; import { generateId } from "@/shared/utils/id-generator"; import { PriceWatch } from "@/shared/types/storage"; import { scheduleWatch } from "@/core/monitor/price-monitor";
const historyStore = useHistoryStore(); const queryStore = useQueryStore(); const router = useRouter(); const platforms: SupportedPlatform[] = ["ctrip", "qunar", "fliggy", "tongcheng"];
const section = ref("watching"); const selectedJourneyKey = ref<string>(); const previousSnapshotId = ref<string>(); const currentSnapshotId = ref<string>(); const targetPrice = ref<number>(); const monitorEnabled = ref(true);
const sectionOptions = [{ value: "watching", label: "关注中" }, { value: "recent", label: "最近查询" }, { value: "expired", label: "已过期" }];
const journeys = computed(() => buildJourneySummaries(historyStore.snapshots)); const watchedKeys = computed(() => new Set(historyStore.watches.map((watch) => watch.journeyKey)));
const sectionJourneys = computed(() => { if (section.value === "watching") return journeys.value.filter((journey) => watchedKeys.value.has(journey.journeyKey)); if (section.value === "expired") return journeys.value.filter((journey) => journey.departureState === "expired"); return journeys.value.filter((journey) => journey.departureState === "upcoming"); });
const selectedJourney = computed(() => journeys.value.find((journey) => journey.journeyKey === selectedJourneyKey.value) || sectionJourneys.value[0]); const currentSnapshot = computed(() => selectedJourney.value?.snapshots.find((item) => item.id === currentSnapshotId.value) || selectedJourney.value?.latest); const comparison = computed(() => { const journey = selectedJourney.value; const previous = journey?.snapshots.find((item) => item.id === previousSnapshotId.value); return previous && currentSnapshot.value && previous.id !== currentSnapshot.value.id ? compareSnapshots(previous, currentSnapshot.value) : undefined; });
const matrixRows = computed(() => currentSnapshot.value ? buildFlightPriceMatrix(currentSnapshot.value) : []); const trendPoints = computed(() => buildTrendPoints(selectedJourney.value?.snapshots || [])); const snapshotOptions = computed(() => selectedJourney.value?.snapshots.map((item) => ({ value: item.id, label: `${formatTime(item.updatedAt)} · ${priceText(snapshotLowest(item))}` })) || []); const currentWatch = computed(() => selectedJourney.value && historyStore.watches.find((item) => item.journeyKey === selectedJourney.value!.journeyKey)); const freshnessColor = computed(() => ({ fresh: "green", recent: "blue", historical: "orange", stale: "red" })[freshness(selectedJourney.value?.latest.updatedAt || new Date().toISOString()).level]); const decisionText = computed(() => { const journey = selectedJourney.value; if (!journey) return ""; if (journey.sampleCount < 3) return "样本不足，仅展示真实查询记录；建议重新比价后再决定。"; const gap = (journey.latestLowest || 0) - (journey.historicalLow || 0); return gap <= 0 ? "当前价格已达到本地历史低点，订票前请重新验证。" : `当前价格比本地历史低点高 ¥${gap}，可重新比价确认。`; });
const legacyRoundTrip = computed(() => selectedJourney.value?.latest.query.tripType === "roundtrip" && selectedJourney.value.latest.dataScopeVersion !== 2);
const canMonitor = computed(() => {
  const snapshot = selectedJourney.value?.latest;
  return Boolean(snapshot && (snapshot.query.tripType !== "roundtrip" || Object.values(snapshot.roundTripPackages || {}).flat().length));
});
onMounted(async () => { await historyStore.fetchHistory(); selectJourney(sectionJourneys.value[0]?.journeyKey || journeys.value[0]?.journeyKey); }); watch(sectionJourneys, (items) => { if (!items.some((item) => item.journeyKey === selectedJourneyKey.value)) selectJourney(items[0]?.journeyKey); });
const monitorSummary = computed(() => { const watch = currentWatch.value; if (!watch) return ""; if (!canMonitor.value) return "往返监控仅支持平台明确展示的原生套餐总价。"; if (!watch.monitorEnabled) return "仅保存关注；不会自动打开平台查询。"; if (watch.lastError) return `最近检查：${watch.lastError}`; return `自动监控每 6 小时检查一次；下次检查：${watch.nextRunAt ? formatTime(watch.nextRunAt) : "待安排"}`; });
function selectJourney(key?: string) { if (!key) return; selectedJourneyKey.value = key; const journey = journeys.value.find((item) => item.journeyKey === key); currentSnapshotId.value = journey?.snapshots[0]?.id; previousSnapshotId.value = journey?.snapshots[1]?.id; const watch = historyStore.watches.find((item) => item.journeyKey === key); targetPrice.value = watch?.targetPrice; monitorEnabled.value = watch?.monitorEnabled ?? true; }
function rerunJourney() { if (!selectedJourney.value) return; queryStore.setQuery({ ...selectedJourney.value.latest.query }); router.push("/"); }
function saveWatch() { const journey = selectedJourney.value; if (!journey) return; const old = currentWatch.value; const effectiveMonitoring = canMonitor.value && monitorEnabled.value; let watch: PriceWatch = { id: old?.id || generateId("watch"), journeyKey: journey.journeyKey, originCity: journey.latest.query.originCity, originCityCode: journey.latest.query.originCityCode, destinationCity: journey.latest.query.destinationCity, destinationCityCode: journey.latest.query.destinationCityCode, departureDate: journey.latest.query.departureDate, targetPrice: targetPrice.value, enabledPlatforms: journey.latest.query.enabledPlatforms, query: { ...journey.latest.query }, priceScope: journey.latest.query.tripType === "roundtrip" ? "roundtrip_package" : "oneway", monitorEnabled: effectiveMonitoring, intervalMinutes: old?.intervalMinutes || 360, createdAt: old?.createdAt || new Date().toISOString(), updatedAt: new Date().toISOString() }; if (effectiveMonitoring) watch = scheduleWatch(watch); else watch.nextRunAt = undefined; void historyStore.saveWatch(watch); }
function removeWatch() { if (currentWatch.value) void historyStore.deleteWatch(currentWatch.value.id); }
function openBooking(flight: FlightResult) { if (typeof chrome !== "undefined" && chrome.runtime) chrome.runtime.sendMessage({ type: "OPEN_FLIGHT_BOOKING", platform: flight.platform, payload: { flight } }); }
function freshness(value: string) { return getPriceFreshness(value); } function priceOf(flight: FlightResult) { return flight.totalPrice ?? flight.displayedPrice; } function priceText(value?: number) { return value === undefined ? "—" : `¥${value}`; } function deltaText(value?: number) { return value === undefined ? "—" : value === 0 ? "持平" : `${value > 0 ? "+" : ""}¥${value}`; } function deltaClass(value?: number) { return value === undefined || value === 0 ? "muted" : value > 0 ? "up" : "down"; } function platformLabel(platform: SupportedPlatform) { return ({ ctrip: "携程", qunar: "去哪儿", fliggy: "飞猪", tongcheng: "同程" })[platform]; } function formatTime(value: string) { return new Date(value).toLocaleString("zh-CN", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" }); }
</script>

<style scoped>
