var(--shadow-sm)}.overview-card{border-color:color-mix(in srgb,var(--border-color),var(--accent-color) 25%);background:linear-gradient(135deg,var(--accent-soft),var(--bg-secondary) 58%)}.overview-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--space-3)}.journey-heading-copy{min-width:0}.overview-heading h3{margin:3px 0;font-size:18px}.freshness-tag{flex:0 0 auto;align-self:flex-start;white-space:nowrap;margin:0!important}.eyebrow{color:var(--accent-color);font-size:var(--font-caption);font-weight:700;letter-spacing:.04em}.metric-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--space-2);margin:var(--space-4) 0 var(--space-2)}.metric-grid div{background:var(--bg-subtle);border:1px solid var(--border-color);border-radius:8px;padding:var(--space-3);display:flex;flex-direction:column;gap:var(--space-1)}.metric-grid span{font-size:var(--font-caption);color:var(--text-muted)}.metric-grid strong{font-size:18px;color:var(--success-color);font-variant-numeric:tabular-nums}.decision-note{font-size:var(--font-caption);color:var(--text-secondary);margin:var(--space-2) 0}.action-row{display:flex;gap:var(--space-2)}.action-row .ant-input-number{flex:1;min-width:0}.history-tabs{margin-top:var(--space-4)}.panel-card h3{margin:0 0 var(--space-1);font-size:16px}.matrix-list{display:flex;flex-direction:column;gap:var(--space-2);margin-top:var(--space-3)}.matrix-card{padding:var(--space-3);border:1px solid var(--border-color);border-radius:8px;background:var(--bg-subtle)}.matrix-title{display:flex;align-items:center;gap:var(--space-2);font-size:var(--font-caption)}.matrix-title strong{color:var(--accent-color);font-size:var(--font-body);font-variant-numeric:tabular-nums}.matrix-title span{flex:1;color:var(--text-secondary)}.platform-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:var(--space-2);margin-top:var(--space-2)}.platform-grid div{padding:var(--space-2);border:1px solid transparent;border-radius:7px;background:var(--bg-elevated);display:flex;flex-wrap:wrap;gap:var(--space-1);justify-content:space-between;font-size:var(--font-caption)}.platform-grid .best{border-color:var(--success-color);background:var(--success-soft)}.platform-grid span,.platform-grid em{color:var(--text-muted);font-style:normal}.platform-grid strong{color:var(--success-color);font-variant-numeric:tabular-nums}.compare-card{margin-top:var(--space-3)}.snapshot-picker{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-2);margin:var(--space-3) 0}.change-list{display:flex;flex-direction:column;gap:var(--space-1)}.change-row{display:grid;grid-template-columns:1fr auto auto;gap:var(--space-2);padding:var(--space-2);background:var(--bg-subtle);border-radius:7px;font-size:var(--font-caption)}.up{color:var(--danger-color)!important}.down{color:var(--success-color)!important}.snapshot-item{width:100%;display:flex;justify-content:space-between;color:inherit;border:0;border-top:1px solid var(--border-color);background:transparent;padding:var(--space-3) 0;cursor:pointer;font-size:var(--font-caption);font-variant-numeric:tabular-nums}.snapshot-item:hover{color:var(--accent-color)}.snapshot-item b{color:var(--success-color)}.empty-inline,.empty-state{text-align:center;color:var(--text-muted);font-size:var(--font-caption);padding:var(--space-5) 0}.empty-state{margin-top:70px}.empty-state h3{color:var(--text-secondary)}@media(max-width:620px){.page-container{padding:var(--space-4);padding-bottom:80px}.journey-card{min-width:210px}.metric-grid{gap:6px}.metric-grid div{padding:var(--space-2)}.action-row{flex-wrap:wrap}.action-row .ant-input-number{min-width:130px}.snapshot-picker{grid-template-columns:1fr}.overview-heading{align-items:flex-start}}
 .action-row{align-items:center;flex-wrap:wrap}.action-row .ant-input-number{min-width:130px}.monitor-status{margin:var(--space-2) 0 0;color:var(--text-muted);font-size:var(--font-caption)}</style>
